    "id": "answer-eternal-security-2",
    "question": "Is the Bible True?",
    "shortAnswer": "Yes. The Bible presents itself as the inspired Word of God and repeatedly describes God's Word as true, trustworthy, and enduring. The Bible says: “All scripture is given by inspiration of God” (2 Timothy 3:16). And Jesus prayed: “Thy word is truth” (John 17:17). The question of whether the Bible is true ultimately involves whether God can be trusted.",
    "longAnswer": "The Bible does not present itself merely as a collection of human religious opinions. The prophets repeatedly claimed that their message came from God. Peter explains: “Holy men of God spake as they were moved by the Holy Ghost” (2 Peter 1:21). This means that although human beings wrote the Scriptures, their ultimate source was God. The Bible also gives several reasons to trust its message: God is true: Romans 3:4; Titus 1:2. God's Word is truth: Psalm 119:160; John 17:17. God's Word endures: Isaiah 40:8; 1 Peter 1:24-25. Scripture is profitable for teaching and correction: 2 Timothy 3:16-17. Jesus treated Scripture as authoritative: Matthew 4:4, 7, 10; John 10:35. Prophecy provides evidence that God knows the future: Isaiah 46:9-10; John 13:19. Scripture points people to Christ: John 5:39; Luke 24:27. The Bible therefore calls people not to believe blindly, but to examine its claims. The Bereans were commended because they “searched the scriptures daily, whether those things were so” (Acts 17:11). Scripture clearly teaches that its inspired message comes from God and is trustworthy. It does not give a modern scientific description of manuscript transmission, printing, translation, or textual criticism. Those questions can be investigated separately. The foundational biblical claim is that God has given humanity a trustworthy revelation of His truth.",
