    "id": "answer-who-decided-what-books-are-in-the-bible",
    "question": "Who Decided What Books Are in the Bible?",
    "shortAnswer": "The Bible does not describe a single human council deciding which books became Scripture. Instead, Scripture presents inspired writings as possessing divine authority because they came from God.",
    "longAnswer": "Jesus clearly recognized the authority of the Old Testament Scriptures. After His resurrection, He referred to: “the law of Moses, and the prophets, and the psalms” (Luke 24:44). Jesus also repeatedly appealed to Scripture as authoritative. The apostles continued this practice. Paul described the Jews as having been entrusted with: “the oracles of God” (Romans 3:2). Peter provides an especially important New Testament example. Referring to Paul's writings, he says: “some things hard to be understood… which they that are unlearned and unstable wrest, as they do also the other scriptures” (2 Peter 3:16). Peter's wording places Paul's writings in connection with the category of Scripture. Scripture does not describe a single meeting where a group of leaders sat down and created the biblical canon. The recognition of particular books as authoritative developed within the biblical community, while the authority of Scripture itself is presented as originating with God. This distinction is important: A council does not make God's Word inspired. Rather, people recognize and receive writings because they are believed to possess divine authority. The exact historical development of the canon involves questions beyond what Scripture itself records.",
