    "shortAnswer": "Seraphim are heavenly beings described in Isaiah's vision of God's throne. They continually proclaim God's holiness and worship Him.",
    "longAnswer": "Isaiah 6 gives the clearest biblical description: “Above it stood the seraphims: each one had six wings” (Isaiah 6:2). They proclaim: “Holy, holy, holy, is the LORD of hosts” (Isaiah 6:3). One of the seraphim also takes a live coal from the altar and touches Isaiah's lips, symbolizing the removal of his guilt and the cleansing of his sin (Isaiah 6:6-7). The scene emphasizes God's holiness. Isaiah is overwhelmed by his own uncleanness when he sees God's glory. The seraphim's worship therefore reinforces a central biblical truth: God's presence is perfectly holy. Seraphim are mentioned specifically in Isaiah 6. The Bible gives us less information about them than about angels generally. It does not provide a complete hierarchy of all heavenly beings. Therefore, elaborate systems ranking angels should not be treated as explicit biblical teaching unless Scripture itself supports them.",
