    "id": "answer-when-is-jesus-coming-back",
    "question": "When Is Jesus Coming Back?",
    "shortAnswer": "The Bible teaches that Jesus Christ will return personally, visibly, and gloriously. However, Jesus specifically said that the exact day and hour of His return are not revealed to human beings.",
    "longAnswer": "Jesus said: “But of that day and hour knoweth no man” (Matthew 24:36). He therefore warned His followers not to attempt to calculate the exact date. At the same time, Jesus gave signs that would precede His coming, including deception, wars, famines, pestilences, persecution, false prophets, and the worldwide proclamation of the gospel (Matthew 24:4-14). His return will not be secret or invisible. Jesus said: “For as the lightning cometh out of the east, and shineth even unto the west; so shall also the coming of the Son of man be” (Matthew 24:27). Revelation describes Him coming with the clouds, and says: “every eye shall see him” (Revelation 1:7). Paul says the Lord will descend from heaven with a shout, with the voice of the archangel, and with the trumpet of God (1 Thessalonians 4:16). Scripture gives signs and describes the manner of Christ's return, but it does not give us permission to set a date. The appropriate response is therefore not date-setting but watchfulness and readiness.",
