    "shortAnswer": "The Bible does not reveal the exact date or hour of Christ's second coming. It teaches that the return will occur after the gospel has been proclaimed to the world and that believers should remain ready.",
    "longAnswer": "Jesus said: “But of that day and hour knoweth no man” (Matthew 24:36). This prevents Christians from legitimately calculating a precise date. Jesus did, however, say: “this gospel of the kingdom shall be preached in all the world for a witness unto all nations; and then shall the end come” (Matthew 24:14). The sequence is important. The gospel is proclaimed to the nations, and then the end comes. Jesus also compared His coming to the days of Noah (Matthew 24:37-39). The issue was not that people lacked a calendar date. The issue was that they were unprepared. Paul similarly describes the day of the Lord as coming unexpectedly upon those who are spiritually unprepared (1 Thessalonians 5:1-6). The Bible does not give the precise date. Therefore, anyone claiming to know the exact day of Christ's return is claiming knowledge that Jesus said human beings do not possess.",
