    "id": "answer-what-is-666",
    "question": "What Is 666?",
    "shortAnswer": "666 is the number associated with the beast in Revelation 13. Scripture says it is “the number of the beast” and “the number of a man.”",
    "longAnswer": "Revelation says: “Here is wisdom. Let him that hath understanding count the number of the beast: for it is the number of a man; and his number is Six hundred threescore and six” (Revelation 13:18). The number is therefore specifically connected with the beast's identity and authority. The verse says that understanding is required to “count” or “calculate” the number. In the ancient world, letters could also have numerical values, so many interpreters have understood the number as connected with a name. However, the Bible itself does not provide the name in Revelation 13:18. Scripture does not say that every occurrence of the number 666 is automatically the mark of the beast. Nor does it say that Christians should obsess over finding 666 in modern prices, identification numbers, products, or technologies. The number is specifically associated with the beast described in Revelation 13. The central issue of Revelation 13-14 is worship and allegiance, not mathematical superstition.",
