    "id": "answer-what-is-the-abomination-of-desolation",
    "question": "What Is the Abomination of Desolation?",
    "shortAnswer": "The “abomination of desolation” is a prophetic expression used by Daniel and quoted by Jesus. It refers to a profaning or desolating power associated with opposition to God's worship and sanctuary.",
    "longAnswer": "Daniel uses the expression in connection with the prophetic “abomination” and desolation (Daniel 9:27; 11:31; 12:11). Jesus later said: “When ye therefore shall see the abomination of desolation, spoken of by Daniel the prophet, stand in the holy place…” (Matthew 24:15). He connected it with a warning to flee (Matthew 24:16). The parallel in Mark says: “the abomination of desolation, spoken of by Daniel the prophet, standing where it ought not” (Mark 13:14). Luke's parallel describes Jerusalem surrounded by armies (Luke 21:20). This shows that the prophecy had an important historical application involving Jerusalem while also appearing within Jesus' broader end-time discourse. The phrase should not be reduced to one modern object or event without examining all its biblical uses. Daniel provides the prophetic foundation, while Jesus applies Daniel's language within His teaching about Jerusalem and the end.",
