    glowTop: "rgba(230, 160, 150, 0.22)",
    glowBottom: "rgba(240, 190, 140, 0.18)",
    eyebrow: "#f6ce74",
    reference: "#f0c9c4",
    divider: "rgba(255, 255, 255, 0.16)",
    frame: "rgba(255, 255, 255, 0.14)",
    motifColor: "rgba(240, 200, 180, 0.16)"
